{
  "up": "Select molecule_dictionary.chembl_id AS chembl_id, molecule_dictionary.pref_name AS compound_name, compound_structures.canonical_smiles AS canonical_smiles From molecule_dictionary Join compound_records On molecule_dictionary.molregno = compound_records.molregno Join docs On compound_records.doc_id = docs.doc_id Join activities On compound_records.record_id = activities.record_id Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where docs.chembl_id = 'CHEMBL5729568' And compound_structures.canonical_smiles Is Not Null Group By molecule_dictionary.chembl_id molecule_dictionary.pref_name compound_structures.canonical_smiles Sort By molecule_dictionary.chembl_id molecule_dictionary.pref_name compound_structures.canonical_smiles"
}
